ToolUseBlock(id='toolu_01Ky6ZRLxBhbcsemX6Ennvo4', name='Bash', input={'command': 'python3 -I -c "
import json,sys
d=json.load(open(sys.argv[1]))
for c in d['customers']:
    s=c['services']
    cl=s.get('cards.list',{})
    r=cl.get('response',{})
    cards=(r.get('data') or {}).get('cards') or []
    print('==',c['customerNo'],c['firstName'],'list http',cl.get('http'),'exit',(r.get('data') or {}).get('exitState'),'valid',(r.get('data') or {}).get('validCardsCount'), 'res',json.dumps(r.get('result',{}).get('code')),r.get('result',{}).get('message'), 'delay',cl.get('gecikmeSaniye'))
    for k in cards: print('   card',k)
    for svc in ('cards.balance','statement.week.get'):
        for cn,v in (s.get(svc) or {}).items():
            if not isinstance(v,dict) or 'http' not in v: continue
            dd=(v.get('response') or {}).get('data') or {}
            if svc=='cards.balance':
                cur={k:(dd[k]['statementPaymentStatus'],dd[k]['statementDebt'],dd[k]['minPayment'],dd[k]['remainingDebt'],dd[k]['remainingMinPayment'],dd[k]['totalDebt'],dd[k].get('remainAutomaticPaymentAmount')) for k in ('debtTL','debtUSD','debtEUR','debtGBP') if k in dd}
                print('   bal',cn,v['http'],v.get('gecikmeSaniye'),dd.get('productName'),dd.get('statementDate'),dd.get('lastPayDate'),dd.get('statementPaymentStatus'),dd.get('automaticPaymentFlag'),cur, (v.get('response') or {}).get('result',{}).get('message') if v['http']!=200 else '')
            else:
                print('   wk',cn,v['http'],{k:dd.get(k) for k in ('statementWeek','statementDay','nextStatementDate','nextLastPayDate','relationType','relatedCardNumber','relatedCardProductName')}, [k for k in dd if k not in ('cardNumber','cardNumberLast4','productName','statementWeek','statementDay','statementDate','lastPayDate','nextStatementDate','nextLastPayDate','relationType','relatedCardNumber','relatedCardProductName')])
    for svc in ('statement.week.decide','statement.week.change'):
        for cn,wk in (s.get(svc) or {}).items():
            for w,v in wk.items():
                dd=(v.get('response') or {}).get('data') or {}
