def g_exit(name, desc, intent, target):
    return {"name": name, "node_type": "code", "description": desc,
            "condition": {"operator": "matches_intent", "description": intent},
            "passthrough": True, "passthrough_default_transition": target, "on_enter": {"type": "silent"},
            "disable_inactivity_monitor": True, "pre_actions": [code_fn(G_EXIT % name)],
            "excluded_nodes": END_KEYS + PASS_KEYS, "transitions": [always(target)]}

def g_back(name, desc, intent, code, extra):
    return {"name": name, "node_type": "code", "description": desc,
            "condition": {"operator": "matches_intent", "description": intent},
            "passthrough": True, "passthrough_default_transition": "__previous__", "on_enter": {"type": "silent"},
            "disable_inactivity_monitor": True, "pre_actions": [code_fn(code)],
            "excluded_nodes": END_KEYS + PASS_KEYS, "transitions": extra + [always("__previous__")]}

