# ----------------------------------------------------------------------------------------------- builders

def always(t):
    return {"target_node": t, "description": "always", "condition": {"operator": "always"}}

def eq(t, var, val, desc=None):
    return {"target_node": t, "description": desc or f"{var} is {val}",
            "condition": {"logic": "or", "conditions": [{"variable": var, "operator": "equals", "operand": val}]}}

def code_fn(code):
    return {"type": "function", "function": {"name": "code_exec", "handler": "__function__:code_exec",
            "parameters": {"type": "object", "properties": {
                "code": {"type": "string", "default": code.strip("\n") + "\n"},
                "timeout_ms": {"type": "number", "default": 10000}}}}}

def code_node(name, code, transitions, on_enter=None):
    return {"name": name, "node_type": "code", "passthrough": True,
            "passthrough_default_transition": transitions[-1]["target_node"],
            "on_enter": on_enter or {"type": "silent"}, "disable_inactivity_monitor": True,
            "pre_actions": [code_fn(code)], "transitions": transitions}

def api_node(name, path, body, mapping, nxt, timeout=15000, retries=1, on_enter=None):
    props = {"customerNo": {"type": "string", "description": "Customer number from the call variable.", "default": "{{customerNumber}}"}}
    props.update(body)
    return {"name": name, "node_type": "api_request", "passthrough": True, "passthrough_default_transition": nxt,
            "on_enter": on_enter or {"type": "silent"}, "disable_inactivity_monitor": True,
            "pre_actions": [{"type": "function", "config": {"timeoutMs": timeout, "maxRetries": retries},
                             "function": {"name": name, "handler": "__function__:api_call",
                                          "description": "Engine-run call to " + path,
                                          "parameters": {"type": "object", "properties": {
                                              "url": {"type": "string", "default": BASE + path},
                                              "method": {"type": "string", "default": "POST"},
                                              "headers": {"type": "object", "properties": {"Content-Type": {"type": "string", "default": "application/json"}}},
                                              "body": {"type": "object", "properties": props, "required": list(props)}}}}}],
            "response_mapping": [{"path": p, "variable": v} for p, v in mapping],
            "transitions": [always(nxt)]}

def end_node(name, fn, line):
    return {"name": name, "node_type": "end_call", "on_enter": {"type": "silent"}, "disable_inactivity_monitor": True,
            "transitions": [], "terminal": {"type": "function", "function": {
                "name": fn, "handler": "__function__:end_call",
                "parameters": {"type": "object", "properties": {
                    "message_mode": {"type": "string", "default": "custom"},
                    "spoken_message": {"type": "string", "default": line}}}}}}

NO_TOOL = ("No tool call is allowed in this step. ")

def ask_node(name, task, schema, answer_vars):
    conds = [{"variable": v, "operator": "not_equals", "operand": "none"} for v in answer_vars]
    for x in schema:
        x.setdefault("min_confidence", 0.6)
    return {"name": name, "node_type": "conversation",
            "on_enter": {"type": "tts", "text": "{{q_say}}"},
            "task_message": NO_TOOL + task + "\n\nThe question you are waiting on (ask it again briefly, in Turkish, at the end of your reply): {{q_short}}\n\n" + NO_TOOL,
            "extraction_schema": schema,
            "max_node_turns": 8, "max_turn_transition": "end_fail",
            "transitions": [{"target_node": "brain", "description": "The caller answered the question",
                             "condition": {"logic": "or", "conditions": conds}}]}

